    .map(c => {
      if (_.isFunction(c.browserTransformFn)) {
        return c.browserTransformFn;
      }
    })
    .filter(f => _.isFunction(f));
  return functions.length === 0
    ? void 0
    : function (entity) {
        for (let index = functions.length - 1; index >= 0; index--) {
