(error: unknown, res: ExpressResponse) => {
    let status = 500;
    let message = 'Internal Server Error';
    let details: any = undefined;
    let success = false;
    let code = undefined;
    let context = undefined;
    if (typeof error === 'function') {
      const obj: RestErrorResponseWrapper = error(res) || {};
      status = obj.status || 400;
      message = obj.message;
      details = obj.details;
      code = obj.code;
      context = obj.context;
    } else if (typeof error === 'string') {
      message = error;
      status = 400;
    } else if (error instanceof Error) {
      message = error.message;
      //#region @backend
      details = process.env.NODE_ENV !== 'production' ? error.stack : undefined;
      //#endregion
    } else {
      message = 'Unexpected error';
      details = error;
    }

    const errroResult = {
      success,
      message,
      details,
      code,
      context,
      [CoreModels.TaonHttpErrorCustomProp]: true,
    } as RestErrorResponseWrapper;

    // console.error(errroResult);
    if (errroResult.code) {
      console.error(`Error code key: ${errroResult.code}`);
    }
    if (!_.isUndefined(errroResult.status)) {
      console.error(`Error status code: ${errroResult.status}`);
    }
    if (errroResult.message) {
      console.error(errroResult.message);
    }
    if (errroResult.details) {
      console.error(errroResult.details);
    }

