          for (const [k, v] of Object.entries(parentCfg.methods)) {
            clonedMethods[k] = {
              ...v,
              parameters: { ...v.parameters }, // shallow clone parameters too
            };
          }

          cfg = {
            ...parentCfg,
            methods: clonedMethods,
          };
        }
      }

      Reflect.defineMetadata(Symbols.metadata.options.controller, cfg, target);
